import type { MainNavContextType, MainNavProps } from "./main-nav.types";

import React, { forwardRef, useState, useEffect, useMemo, useRef } from "react";
import { clsx } from "clsx";
import { ThemeProvider, useTheme } from "@theme";

import { MainNavClasses, StyledMainNav } from "./main-nav.styles";
import { MainNavContent, MainNavFooter, MainNavHeader } from "./subcomponents/main-nav-layout";
import { MainNavDivider, MainNavItem, MainNavIndicator } from "./subcomponents/main-nav-items";
import { MainNavSelect } from "./subcomponents/main-nav-select";
import {
  MainNavUser,
  MainNavUserAvatar,
  MainNavUserNotifications,
} from "./subcomponents/main-nav-user";
import { MainNavContext } from "./hooks/use-main-nav";
import { MainNavBrand, MainNavCollapseTrigger } from "./subcomponents/main-nav-brand";
import { MainNavMenu } from "./subcomponents/main-nav-menu";
import { createMainNavTheme } from "./utils/create-main-nav-theme";
import { MainNavInlineBadge } from "./subcomponents/main-nav-inline-badge";

const MainNavRoot = forwardRef(
  (
    {
      className,
      variant = "default",
      "aria-label": ariaLabel = "Main Navigation",
      defaultCollapsed = false,
      collapsed: controlledCollapsed,
      onCollapseChange,
      children,
      ...props
    }: MainNavProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const mainNavTheme = useMemo(() => theme && createMainNavTheme(theme), [theme]);

    const rootClasses = clsx(MainNavClasses.root, className);

    const [isCollapsed, setIsCollapsed] = useState(defaultCollapsed);

    useEffect(() => {
      if (controlledCollapsed !== undefined) {
        setIsCollapsed(controlledCollapsed);
      }
    }, [controlledCollapsed]);

    const finalCollapsedState =
      controlledCollapsed !== undefined ? controlledCollapsed : isCollapsed;
    const dataMainNavState = finalCollapsedState ? "collapsed" : "expanded";

    const handleCollapse = React.useCallback(
      (collapsed: boolean) => {
        setIsCollapsed(collapsed);
        onCollapseChange?.(collapsed);
      },
      [onCollapseChange],
    );

    const contentRef = useRef<HTMLDivElement>(null);

    const mainNavContextValue: MainNavContextType = useMemo(
      () => ({
        dataMainNavState,
        setIsCollapsed: handleCollapse,
        collapsed: finalCollapsedState,
        theme: mainNavTheme,
        contentRef,
      }),
      [dataMainNavState, handleCollapse, finalCollapsedState, mainNavTheme],
    );

    // MainNav is a special component in its styling, we need to clear out the theme
    // to avoid passing down unwanted styles to components used inside the main-nav
    return (
      <ThemeProvider as="aside" theme={mainNavTheme}>
        <nav aria-label={ariaLabel} style={{ height: "100%" }}>
          <MainNavContext.Provider value={mainNavContextValue}>
            <StyledMainNav
              ref={ref}
              className={rootClasses}
              currentTheme={mainNavTheme}
              data-main-nav-state={finalCollapsedState ? "collapsed" : "expanded"}
              variant={variant}
              {...props}
            >
              {children}
            </StyledMainNav>
          </MainNavContext.Provider>
        </nav>
      </ThemeProvider>
    );
  },
);
MainNavRoot.displayName = "MainNav";

export const MainNav = Object.assign(MainNavRoot, {
  Header: MainNavHeader,
  Content: MainNavContent,
  Footer: MainNavFooter,
  Brand: MainNavBrand,
  CollapseTrigger: MainNavCollapseTrigger,
  Item: MainNavItem,
  Divider: MainNavDivider,
  Indicator: MainNavIndicator,
  Menu: MainNavMenu,
  MenuTrigger: MainNavMenu.Trigger,
  MenuContent: MainNavMenu.Content,
  MenuLabel: MainNavMenu.Label,
  MenuGroup: MainNavMenu.Group,
  MenuSub: MainNavMenu.Sub,
  MenuSubTrigger: MainNavMenu.SubTrigger,
  MenuSubContent: MainNavMenu.SubContent,
  Select: MainNavSelect,
  User: MainNavUser,
  UserAvatar: MainNavUserAvatar,
  UserNotifications: MainNavUserNotifications,
  InlineBadge: MainNavInlineBadge,
});

export default MainNav;
